package net.civeira.phylax.features.access.tenant.application.policy;

import jakarta.enterprise.event.Observes;
import net.civeira.phylax.common.security.Actor;
import net.civeira.phylax.features.access.tenant.application.usecase.create.TenantCreateAuthorizationDecision;

public class CreateOnlyForRoot {

  /**
   * Constant for admin role
   *
   * @autogenerated ConditionPolicyGenerator
   */
  private static final String ROL_ADMIN = "admin";

  /**
   * Constant for platformGlobalAccess scope
   *
   * @autogenerated ConditionPolicyGenerator
   */
  private static final String SCOPE_PLATFORM_GLOBAL_ACCESS = "platform:global_access";

  /**
   * @autogenerated ConditionPolicyGenerator
   * @param allowDecision
   */
  public void checkAllow(@Observes TenantCreateAuthorizationDecision allowDecision) {
    Actor actor = allowDecision.getActor();
    System.err.println("Scope: " + actor.hasScope(SCOPE_PLATFORM_GLOBAL_ACCESS));
    System.err.println("Role: " + actor.hasRole(ROL_ADMIN));
    System.err.println("=========================");
    if (!(actor.hasScope(SCOPE_PLATFORM_GLOBAL_ACCESS) && actor.hasRole(ROL_ADMIN))) {
      allowDecision.deny("Create only for root");
    }
  }
}
